create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,premium_until timestamptz,created_at timestamptz default now());
create table public.papers(id bigint generated by default as identity primary key,subject text not null,paper_code text,semester text,year integer not null,title text not null,pdf_url text not null,is_premium boolean default true,created_at timestamptz default now());
create table public.payments(id bigint generated by default as identity primary key,user_id uuid references auth.users(id) on delete cascade,razorpay_order_id text,razorpay_payment_id text,plan text,amount integer,status text default 'created',created_at timestamptz default now());
alter table public.profiles enable row level security;alter table public.papers enable row level security;alter table public.payments enable row level security;
create policy "own profile" on public.profiles for select to authenticated using(auth.uid()=id);
create policy "view papers" on public.papers for select to authenticated using(is_premium=false or exists(select 1 from public.profiles p where p.id=auth.uid() and p.premium_until>now()));
create policy "own payments" on public.payments for select to authenticated using(user_id=auth.uid());